mapper.select:
/* selectMasterMpSoBuyerGrLockPopList */ SELECT A.CODE AS GR_MONTH, A.COMPANY_CODE AS BUYER, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.COMPANY_CODE) AS BUYER_NAME, A.TEXT1 AS CHANGE_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.TEXT1) AS CHANGE_USER_NAME, A.FLAG AS LOCK_YN, TO_CHAR(TO_DATE(A.ADD_DATE, 'YYYYMMDD'), 'YYYY/MM/DD') AS CHANGE_DATE FROM ICOMCOD2 A WHERE 1=1 AND A.TYPE = 'NOGR'
AND A.CODE IN
#{month}
AND A.COMPANY_CODE IN
#{buyer}
ORDER BY A.FLAG DESC, A.ADD_DATE DESC, A.COMPANY_CODE


/* selectMasterMpSoBuyerGrLockCnt */
SELECT	COUNT(CODE) AS CNT
FROM	ICOMCOD2 A
WHERE	1=1
AND		A.TYPE = 'NOGR'
AND		A.CODE = #{st_sub_close_month}
AND		A.COMPANY_CODE = #{st_buyer_single}

mapper.update:

/* updateMasterMpSoBuyerGrLock */
UPDATE	ICOMCOD2
SET		TEXT1 = #{st_user_id},
		FLAG = #{GR_FLAG},
		ADD_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD')
WHERE	1=1
AND		TYPE = 'NOGR'
AND		CODE = #{st_sub_close_month}
AND		COMPANY_CODE = #{st_buyer_single}
